//
// Card           : Black Ward
// Set            : lea
// Collector #    : 5

#[test]
fn round_trip() {
    let text = "Enchant creature\nEnchanted creature has protection from black. This effect doesn't remove this Aura.";
    let ast = mtg_grammar::parse(text).expect("parse");
    let reprinted = mtg_grammar::unparse(&ast);
    let ast2 = mtg_grammar::parse(&reprinted).expect("reparse");
    assert_eq!(ast, ast2);
}
